/**
 * Argument parsing per the README:
 * - `--retry <n>` sets the retry count (default 0)
 * - `--retry` without a value is an error
 */
export function parseArgs(argv) {
  let retries = 0
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] !== '--retry') continue
    const value = argv[i + 1]
    if (value === undefined || !/^\d+$/.test(value)) {
      throw new Error('--retry requires a non-negative integer value')
    }
    retries = Number(value)
    i += 1 // skip the consumed value
  }
  return { retries }
}

/**
 * Retry logic per the README: call `fn()` and, on a thrown transient error
 * (`code === 'ETIMEDOUT'` or `'ECONNRESET'`), retry up to `retries` times with
 * a short backoff delay. Non-transient errors propagate immediately.
 */

const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

const isTransient = (error) =>
  error != null && typeof error === 'object' && TRANSIENT_CODES.has(error.code)

export async function retryWithBackoff(fn, retries = 0) {
  let attempt = 0
  for (;;) {
    try {
      return await fn()
    } catch (error) {
      if (!isTransient(error) || attempt >= retries) throw error
      attempt += 1
      // 1ms base, doubling per retry, capped so tests stay fast.
      await sleep(Math.min(64, 2 ** (attempt - 1)))
    }
  }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { parseArgs } from '../src/args.js'

test('args: default retries is 0', () => {
  assert.deepEqual(parseArgs(['run']), { retries: 0 })
})

test('args: --retry <n> sets the count', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '3']), { retries: 3 })
})

test('args: --retry without value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry']))
})

test('args: --retry before the command also works', () => {
  assert.deepEqual(parseArgs(['--retry', '2', 'run']), { retries: 2 })
})

test('args: --retry with a non-numeric value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry', 'many']))
})

test('args: --retry with a negative value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry', '-1']))
})

test('args: --retry followed by another flag is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry', '--verbose']))
})

test('args: last --retry wins when repeated', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '1', '--retry', '5']), { retries: 5 })
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { retryWithBackoff } from '../src/retry.js'

const transient = (message) => {
  const error = new Error(message)
  error.code = 'ETIMEDOUT'
  return error
}

const reset = (message) => {
  const error = new Error(message)
  error.code = 'ECONNRESET'
  return error
}

test('retry: succeeds on the first call', async () => {
  const result = await retryWithBackoff(() => Promise.resolve('ok'), 3)
  assert.equal(result, 'ok')
})

test('retry: retries a transient failure then succeeds', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(transient('timeout'))
    return Promise.resolve('ok')
  }, 3)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: gives up after retries are exhausted', async () => {
  await assert.rejects(() => retryWithBackoff(() => Promise.reject(transient('timeout')), 2))
})

test('retry: ECONNRESET is transient and gets retried', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(reset('reset'))
    return Promise.resolve('ok')
  }, 3)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: non-transient errors are not retried', async () => {
  let calls = 0
  const denied = () => {
    calls += 1
    const error = new Error('denied')
    error.code = 'EACCES'
    return Promise.reject(error)
  }
  await assert.rejects(() => retryWithBackoff(denied, 3))
  assert.equal(calls, 1)
})

test('retry: synchronous throws are handled like rejections', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) throw transient('timeout')
    return 'ok'
  }, 3)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: with 0 retries a transient error fails after one call', async () => {
  let calls = 0
  await assert.rejects(() => retryWithBackoff(() => {
    calls += 1
    return Promise.reject(transient('timeout'))
  }, 0))
  assert.equal(calls, 1)
})

test('retry: exhausts retries with one call per attempt', async () => {
  let calls = 0
  await assert.rejects(() => retryWithBackoff(() => {
    calls += 1
    return Promise.reject(transient('timeout'))
  }, 3))
  assert.equal(calls, 4)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { retryWithBackoff } from '../src/retry.js'

// Deterministic PRNG (mulberry32) so the statistical acceptance test is
// reproducible and never flaky.
function mulberry32(seed) {
  return function next() {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const LOSS = 0.3
const RUNS = 1000

// A simulated weak network: each attempt drops the packet with 30% probability
// and throws a transient error; otherwise the request succeeds.
const flakyNetwork = (rand) => async () => {
  if (rand() < LOSS) {
    const error = new Error('packet lost')
    error.code = 'ETIMEDOUT'
    throw error
  }
  return 'ok'
}

test('acceptance: with 30% packet loss, retries give >= 99% success', async () => {
  const rand = mulberry32(0xc0ffee)
  let ok = 0
  for (let i = 0; i < RUNS; i += 1) {
    try {
      await retryWithBackoff(flakyNetwork(rand), 3)
      ok += 1
    } catch {
      // request failed after exhausting all retries
    }
  }
  const rate = ok / RUNS
  assert.ok(rate >= 0.99, `success rate ${rate} is below 99% (${ok}/${RUNS})`)
})

test('acceptance: without retries the same network stays far below 99%', async () => {
  const rand = mulberry32(0xc0ffee)
  let ok = 0
  for (let i = 0; i < RUNS; i += 1) {
    try {
      await retryWithBackoff(flakyNetwork(rand), 0)
      ok += 1
    } catch {
      // expected: roughly 30% of runs fail
    }
  }
  const rate = ok / RUNS
  assert.ok(rate < 0.95, `baseline success rate ${rate} should be well below 99%`)
})

