import('./src/retry.js').then(async ({ retryWithBackoff }) => {
  function mulberry32(seed) {
    return function next() {
      seed |= 0; seed = (seed + 0x6d2b79f5) | 0
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296
    }
  }
  const LOSS = 0.3, RUNS = 1000
  for (const retries of [0, 1, 2, 3]) {
    const rand = mulberry32(0xc0ffee)
    let ok = 0
    for (let i = 0; i < RUNS; i++) {
      try {
        await retryWithBackoff(async () => {
          if (rand() < LOSS) { const e = new Error('lost'); e.code = 'ETIMEDOUT'; throw e }
          return 'ok'
        }, retries)
        ok++
      } catch {}
    }
    console.log('retries=' + retries + ' success=' + ok + '/' + RUNS + ' rate=' + (ok / RUNS))
  }
})
